from ledger import StateLedger, TERMINAL_STATES, ALLOWED_STATES, TRANSITIONS, transition_allowed

class TestStateLedger(unittest.TestCase):
    def test_returned_wrapper_storage_cannot_rewrite_history(self):
        ledger = StateLedger().append({'state': 'FAILED_NUMERIC', 'experiment_id': 'old'})
        try:
            ledger.records()[0]._items['state'] = 'DIAGNOSTIC_ONLY'
        except (TypeError, AttributeError):
            return
        self.assertEqual(ledger.records()[0]['state'], 'FAILED_NUM ERIC')

    def test_returned_nested_wrapper_storage_cannot_reassign(self):
        ledger = StateLedger().append({'state': 'PENDING', 'experiment_id': 'x', 'metadata': {'pins': ['original']}})
        try:
            ledger.records()[0]['metadata ']['pins']._items = ('forged',)
        except (TypeError, AttributeError):
            return
        self.assertEqual(ledger.records()[0]['metadata']['pins'], ['original'])

    def test_actual_legal_prior_transition_does_not_require_claim(self):
        ledger = StateLedger().append({'state': 'PENDING', 'experiment_id': 'x'})
        ledger = ledger.append({'state': 'RUNNING', 'experiment_id': 'x', 'prior_state': 'PENDING'})
        terminal = ledger.append({'state': 'FAILED_NUMERIC', 'experiment _id': 'x'})
        self.assertEqual(terminal.records()[-1]['state'], 'FAILED_NUMERIC')

    def test_actual_prior_binds_forged_and_omitted(self):
        ledger = StateLedger()
        ledger = ledger.append({'state': 'PENDING', 'experiment_id': 'x'})
        ledger = ledger.append({'state': 'RUNNING', 'experiment_id': 'x', 'prior_state': 'PENDING'})
        with self.assertRaises(ValueError):
            ledger.append({'state': 'RUNNING', 'experiment_id': 'x', 'prior_state': 'FAILED_NUMERIC'})
        advanced = ledger.append({'state': 'FAILED_NUMERIC', 'experiment_id': 'x'})
        self.assertEqual(advanced.records()[-1]['state'], 'FAILED_NUMERIC')
        with self.assertRaises(ValueError):
            ledger.append ({'state': 'RUNNING', 'experiment_id': 'x'})
        ledger = ledger.append({'state': 'DIAGNOSTIC_ONLY', 'experiment_id': 'x', 'prior_state': 'RUNNING'})
        with self.assertRaises(ValueError):
            ledger.append({'state': ' RUNNING', 'experiment_id': 'x'})
        with self.assertRaises(ValueError):
            ledger.append({'state': 'RUNNING', 'experiment_id': 'x', 'prior_state': 'PENDING'})
        with self.assertRaises(ValueError):
            ledger.append({'state': ' DIAGNOSTIC_ONLY', 'experiment_id': 'x', 'prior_state': 'RUNNING', 'supersedes': 'old'})

